mapper.select:
SELECT
id, task_no, step_no, executor_id, operation_type, step_status,
request_params, result_json, error_code, failure_reason,
dispatch_time, start_time, end_time,
created_time, updated_time
FROM operation_task_step
WHERE task_no = #{taskNo}
  AND step_no = #{stepNo}
  AND executor_id = #{executorId}
FOR UPDATE

mapper.update:
UPDATE operation_task_step
SET step_status = #{targetStatus},
    failure_reason = '',
    dispatch_time = #{dispatchTime},
    updated_time = #{dispatchTime}
WHERE task_no = #{taskNo}
  AND step_no = #{stepNo}
  AND executor_id = #{executorId}
  AND step_status = #{currentStatus}

UPDATE operation_task_step
SET step_status = #{targetStatus},
    failure_reason = #{failureReason},
    updated_time = #{updatedTime}
WHERE task_no = #{taskNo}
  AND step_no = #{stepNo}
  AND executor_id = #{executorId}
  AND step_status = #{currentStatus}

mapper.select:
SELECT MIN(step_no)
FROM operation_task_step
WHERE task_no = #{taskNo}
  AND step_no > #{stepNo}

SELECT step.id, step.task_no, step.step_no, step.executor_id, step.operation_type, step.step_status, step.request_params, step.result_json, step.error_code, step.failure_reason, step.dispatch_time, step.start_time, step.end_time, step.created_time, step.updated_time FROM operation_task_step step INNER JOIN operation_task task ON task.task_no = step.task_no WHERE step.step_status = #{stepStatus} AND task.task_status IN
#{taskStatus}
ORDER BY step.updated_time ASC
